export async function execute(args = {}) {
  const found = String(args.text || '').match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || []
  return { emails: [...new Set(found.map((x) => x.toLowerCase()))] }
}

import test from 'node:test'
import assert from 'node:assert'
import { execute } from '../lib/impl.js'
test('emails', async () => {
  const r = await execute({ text: 'a@b.com and A@B.com and c@d.cn' })
  assert.deepEqual(r.emails, ['a@b.com', 'c@d.cn'])
})
